Object.assign(FXSND_B64, {"mus_cem": ""}); Object.assign(FXSND_B64, {"fx_step_1": "", "fx_step_2": "", "amb_wind": "", "amb_night": ""});   // v0.61: шаги и эмбиент (ветер, ночь)
const AMB = { srcs: [], g: null, on: false, map: null, nightG: null, hum: null };
